CREATE TABLE app_sessions(user_id VARCHAR(100) NOT NULL,session_id VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,PRIMARY KEY(user_id,session_id));
CREATE TABLE app_inputs(user_id VARCHAR(100) NOT NULL,request_id VARCHAR(160) NOT NULL,session_id VARCHAR(100) NOT NULL,input_hash VARCHAR(64) NOT NULL,result_cipher CLOB,PRIMARY KEY(user_id,request_id));
CREATE TABLE app_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id VARCHAR(100) NOT NULL,session_id VARCHAR(100) NOT NULL,source_key VARCHAR(240) NOT NULL,kind VARCHAR(32) NOT NULL,channel VARCHAR(24) NOT NULL,payload_cipher CLOB NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,UNIQUE(user_id,source_key));
CREATE INDEX idx_app_event_cursor ON app_events(user_id,session_id,id);
CREATE TABLE app_task_refs(task_id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(100) NOT NULL,session_id VARCHAR(100) NOT NULL,snapshot_hash VARCHAR(64));
CREATE TABLE app_commands(user_id VARCHAR(100) NOT NULL,id_key VARCHAR(160) NOT NULL,input_hash VARCHAR(64) NOT NULL,result_cipher CLOB,PRIMARY KEY(user_id,id_key));
ALTER TABLE backend_channel_links ADD COLUMN app_mode BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE backend_channel_bindings ADD COLUMN app_mode BOOLEAN NOT NULL DEFAULT FALSE;
